                    ["Forest, light", "2"],
                    ["Forest, medium", "3"],
                    ["Glacier", "2"],
                    ["Hills, rolling", "2"],
                    ["Hills, steep (foothills)", "4"],
                    ["Jungle, heavy", "8"],
                    ["Jungle, medium", "6"],
                    ["Marsh, swamp", "8"],
                    ["Moor", "4"],
                    ["Mountains, high", "8"],
                    ["Mountains, low", "4"],
                    ["Mountains, medium", "6"],
                    ["Untraveled plains, grassland, heath", "1"],
                    ["Scrub, brushland", "2"],
                    ["Tundra", "3"]
                ]
            )
    ],
